const fn = new Function(code + "\nreturn { createRowManager };");
const { createRowManager } = fn();
const m = createRowManager();
const a = m.add("a");
const b = m.add("b");
const c = m.add("c");
if (m.move(c, 0) !== true) throw new Error("Moving c to index 0 succeeds.");
if (m.list().map((r) => r.id).join() !== [c, a, b].join()) throw new Error("Order should now be c, a, b.");
if (m.move(999, 0) !== false) throw new Error("Unknown id fails.");
if (m.move(a, 7) !== false) throw new Error("Out-of-range index fails.");
